#!/usr/bin/env python3
"""Freeze and reserve the BTC/ETH hourly lead-lag follower study."""
import gzip,hashlib,json,subprocess,sys,urllib.parse
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];ROUND=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation'));import registry

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
# Reuse the latest successful official public exchangeInfo snapshot from this branch.
obs=ROOT/'research/paper10/observations/20261013T153525467295Z'
exchange_path=obs/'exchange_info.json.gz';raw=gzip.decompress(exchange_path.read_bytes());exchange=json.loads(raw)
prov=json.loads((obs/'http_provenance.json').read_text())
source_info={'path':str(exchange_path.relative_to(ROOT)),'archive_sha256':sha(exchange_path),'raw_sha256':hashlib.sha256(raw).hexdigest(),'received_utc':next(x['received_at_utc'] for x in prov if urllib.parse.urlsplit(x['url']).path.endswith('/api/v3/exchangeInfo'))}
exchange_filters={'snapshot':source_info,'symbols':{a:next(x for x in exchange['symbols'] if x['symbol']==a+'USDT')['filters'] for a in ('BTC','ETH')}}
write(ROUND/'exchange_filters.json',exchange_filters)
prior=ROOT/'research/experiments/20261013T123949Z';priorplan=json.loads((prior/'plan.json').read_text())
data_files=priorplan['data_files']
for asset,files in data_files.items():
 for row in files:
  p=ROOT/row['path'];assert p.exists() and p.stat().st_size==row['bytes'] and sha(p)==row['sha256']
research_paper={'citation':'Sifat, I. M., Mohamad, A., & Mohamed Shariff, M. S. B. (2019). Lead-lag relationship between Bitcoin and Ethereum: Evidence from hourly and daily data. Research in International Business and Finance, 50, 306-321. DOI:10.1016/j.ribaf.2019.06.012.','url':'https://doi.org/10.1016/j.ribaf.2019.06.012','author_page':'https://research.monash.edu/en/publications/lead-lag-relationship-between-bitcoin-and-ethereum-evidence-from-','accessed_utc':'2026-10-13','finding_summary':'The authors report largely bidirectional price discovery from 2017-2018 hourly/daily BTC and ETH data and state intraday traders could barely exploit it. This is a cost-first, two-way, current-history falsification/adaptation test, not a reproduction or edge claim.'}
grid={'directions':[{'leader':'BTC','follower':'ETH'},{'leader':'ETH','follower':'BTC'}],'leader_lookback_minutes':[15,60,240],'fixed_hold_minutes':[60,240,720]}
oos={'start_utc':'2025-09-19T00:00:00Z','end_exclusive_utc':'2026-09-14T00:00:00Z','terminal_execution_utc':'2026-09-14T00:01:00Z','start_day_index':368,'end_day_index':728,'days':360,'warmup_days':365,'fold_days':30,'folds':12,'embargo_days':3}
costs={'initial_capital_usdt':2000,'fee_per_side':0.001,'half_spread_estimate_per_side':0.0001,'slippage_per_side':0.0002,'impact_model':'0.5 * sample_stdev(previous 20 complete UTC daily log returns) * sqrt(order quote budget / previous 20 complete daily quote ADV)','maximum_participation':0.001,'multipliers':[1,2,3],'exchange_filters_source':source_info,'limitations':'No historical L2; spread and slippage are estimates. PERCENT_PRICE_BY_SIDE is checked against prior five-minute quote/base-volume VWAP proxy. Spot long-only; no borrowing/funding.'}
rule=('At each UTC hourly boundary m, use only fully closed 1-minute bars through m-1. For L in {15,60,240} minutes, compute simple leader and follower returns from close[m-1-L] to close[m-1]. Signal only if leader return > 0.005 and leader return - follower return > 0.0025. If flat, buy the follower at the m+1 one-minute open (60 seconds after the close is available), subject to simulated costs and current frozen exchange filters. A configuration holds at most one follower position. At the first hourly boundary m at or after the fixed holding expiry, sell at m+1 open; after an exit attempt, skip signal entry at that same decision boundary. Rejected exits retain actual holdings and retry on later hourly boundaries. Do not backfill missed signals. Do not enter if the scheduled holding expiry is beyond the terminal boundary. Liquidate any remaining units at the common terminal 2026-09-14 00:01 UTC open. Each configuration has its own 2,000 USDT long-only cash account; no scale-ins, leverage, shorting, transfers, yield, or rebalancing.')
gates={'all_1x_2x_3x_returns_positive':True,'minimum_positive_1x_folds':8,'maximum_3x_sample_drawdown_pct':25,'minimum_3x_adjacent_neighbor_positive_fraction':0.60,'minimum_1x_round_trips':4,'minimum_1x_gross_reference_pnl_to_cost':2.5,'no_rejected_or_capacity_filtered_orders':True,'terminal_flat_all_costs':True,'interpretation':'Repeated repository validation history; no untouched holdout or live execution claim.'}
records=registry.read_records(ROOT/'research/automation/registry.jsonl')
plan={'round':ROUND.name,'frozen_at_utc':'2026-10-13T16:44:15Z','direction':'BTC/ETH two-way hourly leader-impulse, long-only lagging-asset follow-through.','hypothesis':'Prior BTC/ETH hourly/daily evidence reports bidirectional price discovery but little intraday profitability. Test a predeclared follower rule at limited activity and full costs; no positive edge is assumed.','source_paper':research_paper,'complete_rule':rule,'parameter_grid':grid,'candidate_configs':18,'reused_comparators':{'source_report':'research/experiments/20261013T123949Z/report.json','source_report_sha256':sha(prior/'report.json'),'config_names':['hold_360d_btc_relative_strength_study','hold_360d_eth_relative_strength_study'],'status':'read-only same-interval references; not recalculated or re-registered'},'time_boundaries':{'input_history_utc':'2024-09-16T00:00:00Z/2026-09-16T00:00:00Z','walk_forward':'12 contiguous fixed 30-day OOS reporting folds; no fitted model or parameter selection within OOS. Positions may span reporting-fold boundaries; cumulative account state is continuous.','history_disclosure':'This historical range has been repeatedly used in repository research and is not an untouched final holdout.',**oos},'execution':{'decision_interval_minutes':60,'signal_available':'UTC hourly boundary after previous 1m candle close, based only on completed bars','execution_delay_seconds':60,'execution_reference':'next UTC minute open from historical OHLCV, used only in this historical test, not live paper10','holding_expiry':'first hourly decision boundary at or after configured hold; exit at next minute open','accounting':'Existing Decimal marketable-IOC kernel with adverse tick rounding, LOT_SIZE flooring, lagged cost inputs, and five-minute VWAP proxy.' ,'exchange_filters_raw_sha256':source_info['raw_sha256']},'costs':costs,'failure_gates':gates,'sensitivity_axes':['leader_lookback_minutes','fixed_hold_minutes'],'data_files':data_files,'prior_trials':{'registry_unique_configurations':len(records),'exact_lead_lag_follower_configuration_found':False,'adjacent_tests':'Repository includes BTC/ETH half-hour and four-hour momentum/reversal tests, daily ratio mean reversion, and daily relative strength; this rule is fingerprint-distinct. Recent neighboring directions are context, not independent market evidence.'}}
write(ROUND/'plan.json',plan)
batch=[]
for direction in grid['directions']:
 for lookback in grid['leader_lookback_minutes']:
  for hold in grid['fixed_hold_minutes']:
   leader,follower=direction['leader'],direction['follower'];name=f'lead_{leader.lower()}_follow_{follower.lower()}_L{lookback}_H{hold}'
   spec={'kind':'strategy','family':'spot-btc-eth-hourly-leadlag-follower-fixed-hold','market':'spot','universe':[leader+'/USDT',follower+'/USDT'],'timeframe':'1m','name':name,'logic':{'signal':rule,'direction':f'{leader} leads; follower {follower} is the only long exposure.','position':'One active position per 2,000 USDT configuration; full affordable cash, no overlap/scale-in, and same-boundary re-entry is skipped after exits.','limitations':'OHLCV proxy backtest, not live orders, not a replication of the paper, repeated development history.'},'parameters':{'leader':leader,'follower':follower,'leader_lookback_minutes':lookback,'fixed_hold_minutes':hold,'leader_return_threshold':0.005,'leader_minus_follower_gap_threshold':0.0025,'decision_interval_minutes':60,'initial_capital_usdt':2000,**oos,'cost_multipliers':[1,2,3],'exchange_filters_sha256':source_info['raw_sha256'],'sensitivity_axes':['leader_lookback_minutes','fixed_hold_minutes']},'sources':[research_paper],'failure_gates':gates}
   p=ROUND/'specs'/(name+'.json');write(p,spec);batch.append({'name':name,'leader':leader,'follower':follower,'lookback_minutes':lookback,'hold_minutes':hold,'fingerprint':registry.fingerprint(spec),'spec':str(p.relative_to(ROOT))})
assert len(batch)==18 and len({x['fingerprint'] for x in batch})==18
write(ROUND/'batch.json',batch);reserved=[]
for x in batch:
 result=subprocess.run([sys.executable,str(ROOT/'research/automation/registry.py'),'reserve',str(ROOT/x['spec'])],cwd=ROOT,capture_output=True,text=True)
 reserved.append({**x,'exit_code':result.returncode,'stdout':result.stdout.strip(),'stderr':result.stderr.strip()})
 if result.returncode:
  write(ROUND/'reserve_partial.json',reserved);raise SystemExit('reserve failed: '+x['name']+' '+result.stdout+' '+result.stderr)
write(ROUND/'reserve.json',reserved)
print(json.dumps({'round':ROUND.name,'candidates_reserved':len(reserved),'unique_fingerprints':len({x['fingerprint'] for x in reserved}),'directions':2,'grid_per_direction':9,'reused_baselines':2},ensure_ascii=False))
